# ---------------------------------------------------------------------------
# EXTRA USE CASES (appended to the parent-derived 198). Each:
#  dict(id, title, description, domain, sub_vertical, effort, win_rate,
#       compliance[], risk_tags[], value_components[], time_to_value,
#       requires=[(category, module, 'required'|'helpful')],
#       enables=[parent_id or new id])
# value_components: [{name, calculationDisplay, multiplier, assumptionKeys[], lowCoeff, highCoeff}]
# ---------------------------------------------------------------------------
def _c(name, disp, mult, keys, lo=0.7, hi=1.3):
    return {"name": name, "calculationDisplay": disp, "multiplier": mult,
            "assumptionKeys": keys, "lowCoeff": lo, "highCoeff": hi}


